package io.knowledgebrain.notification;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.kafka.clients.consumer.*;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.notification.groupreview.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_NOTIFICATION_KAFKA_BOOTSTRAP",matches=".+")
class ReviewLifecycleKafkaIntegrationTest {
 @Test void fourLifecycleFactsUseUnchangedWireContractAndActualOutboxCdc()throws Exception{var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_URL"));ds.setUser("brain_notification");ds.setPassword(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var store=new GroupReviewStore(ds,Clock.systemUTC());var a=new GroupReviewStore.Access(ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),1);var p=store.preference(a,0,true,ReviewFixtures.trace);long at=Math.max(p.enabledAfter()+10,new JdbcTemplate(ds).queryForObject("SELECT max(enabled_after) FROM group_review_source_activation",Long.class)+10);byte[] source=ReviewFixtures.feedback(a,at);var kinds=new HashSet<String>();for(boolean grade:List.of(false,true)){var id=ReviewFixtures.ids.next();for(int v=1;v<=2;v++){var raw=ReviewLifecycleFixtures.event(source,grade,v==1?"RETRACTED":"RESTORED",v,id,at+v);assertTrue(store.accept(ReviewSignal.decode(ReviewSignal.TOPICS.get(grade?4:3),raw)));}}var rows=store.list(a,"ACTIVE","ALL",null,20).items();assertEquals(4,rows.size());var ids=rows.stream().map(v->v.notificationId().toString()).collect(java.util.stream.Collectors.toSet());var expected=new HashMap<String,byte[]>();for(var n:rows)new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,i)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),n.notificationId()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(4,expected.size());var props=NotificationConfiguration.kafka(System.getenv("BRAIN_TEST_NOTIFICATION_KAFKA_BOOTSTRAP"),"/notification-kafka-test","notification-validation-lifecycle-"+ReviewFixtures.ids.next());props.put("auto.offset.reset","earliest");try(var c=new KafkaConsumer<String,byte[]>(props)){c.subscribe(List.of("notification.group-review.v1"));var found=new HashSet<String>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<4&&System.nanoTime()<deadline)for(var record:c.poll(Duration.ofSeconds(1))){if(!ids.contains(record.key()))continue;var e=GroupReviewEnvelopeV1.parseFrom(record.value());assertArrayEquals(expected.get(e.getEventId()),record.value());var n=GroupReviewNotificationV1.parseFrom(e.getPayload());assertEquals(1,e.getEventVersion());assertEquals(a.principalId().toString(),n.getRecipientId());assertEquals(1,n.getSubmissionVersion());kinds.add(n.getChangeKind());assertFalse(new String(record.value(),StandardCharsets.UTF_8).contains("PRIVATE LIFECYCLE"));for(var h:Map.of("id",e.getEventId(),"trace_id",ReviewFixtures.trace,"schema_group","notification","schema_artifact","group-review-events","schema_version","1").entrySet())assertEquals(h.getValue(),new String(record.headers().lastHeader(h.getKey()).value(),StandardCharsets.UTF_8));found.add(e.getEventId());}assertEquals(expected.keySet(),found);}assertEquals(Set.of("FEEDBACK_RETRACTED","FEEDBACK_RESTORED","GRADE_RETRACTED","GRADE_RESTORED"),kinds);}
}
